import {createWorld} from './world.js';
import {PORTS,RUIN,GOODS,newGame,loadGame,saveGame,trade,cargoCount} from './state.js';
const $=id=>document.getElementById(id);let storage;try{storage=localStorage;}catch{storage={getItem(){return null},setItem(){throw Error('Unavailable');}};}
let state=loadGame(storage),world;const keys=new Set();let paused=false,velocity=0,target=null,nearPort=null,activePort=null,activeTab='market',lastTime=performance.now(),elapsed=0,saveTimer=0,hudTimer=0,fireCooldown=0,pirateHull=100,pirateCooldown=0,muted=true,audioCtx=null,toastTimer,largeMap=null;const modal=$('modal');
try{world=createWorld($('world'));$('loading').style.opacity='0';setTimeout(()=>$('loading').remove(),750);}catch(err){$('loading').innerHTML='<h1>HORIZON</h1><p>The ocean needs WebGL to render.</p><p>Enable hardware acceleration in your browser, then reload.</p>';console.error(err);throw err;}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4200);}
function save(){const ok=saveGame(storage,state);$('saved').textContent=ok?'Progress saved on this device':'Saving unavailable in this browser';}
function sound(freq=440,duration=.15,type='sine'){if(muted)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(freq,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.5,audioCtx.currentTime+duration);g.gain.setValueAtTime(.08,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}catch{}}
function setSail(n){state.sail=n;target=null;updateHUD();}
function navigate(x,z,label){if(Math.abs(x)>85||Math.abs(z)>85){toast('Stay within the Emerald Isles on this voyage.');return;}if(PORTS.some(p=>Math.hypot(x-p.x,z-p.z)<p.r*.94)||Math.hypot(x-RUIN.x,z-RUIN.z)<RUIN.r){toast('Choose open water or a port’s harbor marker.');return;}target={x,z,label:label||'Selected waypoint'};state.sail=1;sound(500);updateHUD();}
PORTS.forEach(p=>{const b=document.createElement('button');b.className='port-label';b.setAttribute('aria-label',`Set course for ${p.name}`);b.innerHTML=`<span class="name">${p.name}</span><span class="type">${p.kind}</span><span class="pin">⚓</span>`;b.onclick=()=>{navigate(p.harbor.x,p.harbor.z,p.name);toast(`Course set for ${p.name}.`);};$('labels').appendChild(b);p.label=b;});
const ruinLabel=document.createElement('button');ruinLabel.className='port-label';ruinLabel.innerHTML='<span class="name">Forgotten shores</span><span class="type">UNDISCOVERED</span><span class="pin">◇</span>';ruinLabel.onclick=()=>navigate(RUIN.x+11,RUIN.z,'Forgotten shores');$('labels').appendChild(ruinLabel);
$('world').addEventListener('pointerdown',e=>{if(e.button!==0||paused||modal.open)return;const p=world.pick(e.clientX,e.clientY);if(p)navigate(p.x,p.z);});$('world').addEventListener('wheel',e=>{e.preventDefault();world.zoom(e.deltaY);},{passive:false});
document.querySelectorAll('[data-sail]').forEach(b=>b.onclick=()=>setSail(Number(b.dataset.sail)));document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.key);});
function openModal(){keys.clear();modal.showModal();}function closeModal(){modal.close();activePort=null;largeMap=null;save();}
$('close-modal').onclick=closeModal;modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});modal.addEventListener('close',()=>{keys.clear();activePort=null;largeMap=null;});
function pause(){paused=!paused;$('pause').textContent=paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',paused?'Resume game':'Pause game');toast(paused?'Voyage paused.':'Back at the helm.');}$('pause').onclick=pause;
function enterPort(){if(!nearPort){toast('Sail closer to a harbor to enter port.');return;}activePort=nearPort;state.sail=0;target=null;velocity=0;activeTab='market';if(!state.discovered.includes(activePort.id)){state.discovered.push(activePort.id);state.log.push(`Day ${Math.floor(state.time/1440)+1} — Arrived at ${activePort.name}.`);}renderPort();openModal();sound(660);save();}
$('dock').onclick=enterPort;
function renderPort(){const p=activePort;if(!p)return;const content=$('modal-content');content.innerHTML=`<div class="modal-eyebrow">⚓ ${p.kind}</div><h2>${p.name}</h2><p class="intro">${p.description}</p><div class="port-tabs"><button data-tab="market" class="${activeTab==='market'?'active':''}">Marketplace</button><button data-tab="shipyard" class="${activeTab==='shipyard'?'active':''}">Harbor services</button></div><div id="port-body"></div><div class="cargo-total"><span>Hold: ${cargoCount(state)} / 40 crates</span><span>◈ ${state.gold.toLocaleString()} gold</span></div>`;content.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab;renderPort();});const body=$('port-body');if(activeTab==='market'){body.innerHTML='<div class="trade-row" style="padding-top:0;color:#95b5af"><span>COMMODITY</span><span>BUY</span><span>SELL</span><span></span><span></span></div>'+GOODS.map(g=>`<div class="trade-row"><div><b>${g.icon} &nbsp;${g.name}</b><small>${state.cargo[g.id]} in hold</small></div><span class="price">${p.prices[g.id]}</span><span>${Math.floor(p.prices[g.id]*.85)}</span><button data-buy="${g.id}" ${state.gold<p.prices[g.id]||cargoCount(state)>=40?'disabled':''}>Buy</button><button data-sell="${g.id}" ${!state.cargo[g.id]?'disabled':''}>Sell</button></div>`).join('');body.querySelectorAll('[data-buy],[data-sell]').forEach(b=>b.onclick=()=>{const side=b.dataset.buy?'buy':'sell';const r=trade(state,p,b.dataset.buy||b.dataset.sell,side);toast(r.message);if(r.ok)sound(side==='buy'?650:850);renderPort();updateHUD();save();});}else{const repair=Math.ceil((100-state.hull)*3);body.innerHTML=`<div class="service"><div><b>Restock provisions</b><p>10 days of food and fresh water.</p></div><button class="action-btn" id="resupply" ${state.gold<60||state.supplies>=60?'disabled':''}>60 gold</button></div><div class="service"><div><b>Repair The Wayfarer</b><p>Hull integrity: ${Math.floor(state.hull)}%</p></div><button class="action-btn" id="repair" ${repair===0||state.gold<repair?'disabled':''}>${repair||'Fully repaired'}${repair?' gold':''}</button></div>`;$('resupply').onclick=()=>{if(state.gold<60||state.supplies>=60)return;state.gold-=60;state.supplies=Math.min(60,state.supplies+10);toast('Provisions replenished.');renderPort();updateHUD();save();};$('repair').onclick=()=>{if(state.gold<repair)return;state.gold-=repair;state.hull=100;toast('Your ship is ready for the open sea.');renderPort();updateHUD();save();};}}
function openCargo(){$('modal-content').innerHTML=`<div class="modal-eyebrow">THE WAYFARER · LIGHT CARAVEL</div><h2>The cargo hold</h2><p class="intro">Every crate is a possibility. Trade at the harbors to turn a little gold into a fortune.</p>${GOODS.map(g=>`<div class="service"><div><b>${g.icon} &nbsp; ${g.name}</b><p>${g.desc}</p></div><b>${state.cargo[g.id]} crates</b></div>`).join('')}<div class="cargo-total"><span>${cargoCount(state)} / 40 crates loaded</span><span>◈ ${state.gold.toLocaleString()} gold</span></div>`;openModal();}$('cargo').onclick=openCargo;
function openJournal(){$('modal-content').innerHTML=`<div class="modal-eyebrow">CAPTAIN’S JOURNAL</div><h2>A fortune on the horizon</h2><p class="intro">The sea belongs to those who dare to leave the shore.</p><div class="journal-entry"><small>${state.quest>=2?'COMPLETED · +500 GOLD':'CHAPTER I · A MERCHANT’S FIRST VOYAGE'}</small><h3>The saffron route</h3><p>Buy 3 crates of saffron in Port Aurelia for 80 gold each. Sail northeast to Bellhaven and sell them for 123 gold each. Deliver all 3 to receive a 500 gold commission.</p><p>Delivered: ${state.delivered||0} / 3 crates</p></div><div class="journal-entry"><small>${state.quest===3?'DISCOVERED · +750 GOLD':'CHAPTER II · SECRETS OF THE ISLES'}</small><h3>The Sunken Observatory</h3><p>After completing the saffron route, sail southwest to the forgotten island. Approach its eastern shore to discover the ancient observatory and claim a 750 gold exploration reward.</p></div><h3>Voyage log</h3>${state.log.slice(-8).reverse().map(s=>`<p class="intro" style="margin:10px 0">${s}</p>`).join('')}`;openModal();}$('journal').onclick=openJournal;
function drawMap(canvas,large=false){const ctx=canvas.getContext('2d');const w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);const scale=Math.min(w,h)/150;const to=(x,z)=>[w/2+x*scale,h/2+z*scale];ctx.strokeStyle='#80afa025';ctx.lineWidth=1;for(let x=-70;x<=70;x+=20){let a=to(x,-75),b=to(x,75);ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke();}for(let z=-70;z<=70;z+=20){let a=to(-90,z),b=to(90,z);ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke();}for(const p of [...PORTS,RUIN]){const [x,y]=to(p.x,p.z);ctx.fillStyle='#759b7b';ctx.strokeStyle='#bcb882';ctx.beginPath();for(let i=0;i<30;i++){const a=i/30*Math.PI*2,r=p.r*scale*(1+Math.sin(a*3+.4)*.085+Math.sin(a*7+1)*.055);if(i===0)ctx.moveTo(x+Math.cos(a)*r,y+Math.sin(a)*r);else ctx.lineTo(x+Math.cos(a)*r,y+Math.sin(a)*r);}ctx.closePath();ctx.fill();ctx.stroke();if(p.harbor){const hp=to(p.harbor.x,p.harbor.z);ctx.fillStyle='#e0c58b';ctx.beginPath();ctx.arc(...hp,2.5,0,Math.PI*2);ctx.fill();}if(large){ctx.fillStyle='#efe3b9';ctx.font='14px Georgia';ctx.textAlign='center';ctx.fillText(p.name,x,y-p.r*scale-9);}}if(target){ctx.setLineDash([3,4]);ctx.strokeStyle='#ebcb87';ctx.beginPath();ctx.moveTo(...to(state.x,state.z));ctx.lineTo(...to(target.x,target.z));ctx.stroke();ctx.setLineDash([]);}const [sx,sy]=to(state.x,state.z);ctx.save();ctx.translate(sx,sy);ctx.rotate(-state.heading);ctx.fillStyle='#f5db9d';ctx.shadowColor='#fff4c3';ctx.shadowBlur=8;ctx.beginPath();ctx.moveTo(0,6);ctx.lineTo(-3.5,-4);ctx.lineTo(3.5,-4);ctx.closePath();ctx.fill();ctx.restore();ctx.fillStyle='#92b5a8';ctx.font=large?'13px Georgia':'10px Georgia';ctx.textAlign='center';ctx.fillText('N',w/2,large?22:12);if(pirateHull>0){const [px,py]=to(world.npc.position.x,world.npc.position.z);ctx.fillStyle='#c47863';ctx.beginPath();ctx.arc(px,py,large?4:2,0,Math.PI*2);ctx.fill();}}
function openChart(){$('modal-content').innerHTML='<div class="modal-eyebrow">THE EMERALD ISLES</div><h2>A world beyond the shore</h2><p class="intro">Select a harbor to plot your course. Open water can also be selected as a waypoint. Steering manually cancels your plotted course.</p><canvas id="large-map" class="chart-large" width="660" height="420" aria-label="Interactive sea chart"></canvas><div class="legend"><span>◆ Your ship</span><span>● Harbor</span><span style="color:#d28c73">● Pirate waters</span></div>' ;openModal();largeMap=$('large-map');drawMap(largeMap,true);largeMap.onclick=e=>{const rect=largeMap.getBoundingClientRect(),xx=(e.clientX-rect.left)*largeMap.width/rect.width,zz=(e.clientY-rect.top)*largeMap.height/rect.height;const scale=Math.min(largeMap.width,largeMap.height)/150;const x=(xx-largeMap.width/2)/scale,z=(zz-largeMap.height/2)/scale;const p=PORTS.find(p=>Math.hypot(x-p.x,z-p.z)<p.r+7);if(p){navigate(p.harbor.x,p.harbor.z,p.name);closeModal();}else{navigate(x,z);if(target)closeModal();}};}$('chart').onclick=$('chart-nav').onclick=$('minimap').onclick=openChart;
$('ship-info').onclick=()=>{$('modal-content').innerHTML=`<div class="modal-eyebrow">YOUR FLAGSHIP</div><h2>The Wayfarer</h2><p class="intro">A nimble two-masted caravel, made for coastal trading and bold journeys into unknown waters.</p><div class="service"><span>Hull integrity</span><b>${Math.floor(state.hull)}%</b></div><div class="service"><span>Crew aboard</span><b>24 sailors</b></div><div class="service"><span>Cargo capacity</span><b>${cargoCount(state)} / 40 crates</b></div><div class="service"><span>Armament</span><b>6 light cannons</b></div><p class="intro" style="margin-top:20px">Press Space to fire when a pirate is within 18 leagues. Repairs and provisions are available at every harbor.</p>`;openModal();};
function settings(){$('modal-content').innerHTML=`<div class="modal-eyebrow">VOYAGE OPTIONS</div><h2>Make yourself at home</h2><div class="setting"><label for="audio">Sound effects</label><input id="audio" type="checkbox" ${!muted?'checked':''}></div><div class="setting"><label for="quality">High resolution & shadows</label><input id="quality" type="checkbox" ${highQuality?'checked':''}></div><p class="intro">W / S to raise or lower sail. A / D to steer. Click open water to navigate automatically. Scroll to zoom. E enters a nearby port. J opens your journal; M opens the chart. P pauses the voyage.</p><p class="intro">Your voyage saves automatically in this browser. Closing a panel resumes sailing.</p><button id="restart" class="action-btn">Start a new voyage</button>`;openModal();$('audio').onchange=e=>{muted=!e.target.checked;sound(660);};$('quality').onchange=e=>{highQuality=e.target.checked;world.setQuality(highQuality);};$('restart').onclick=()=>{$('modal-content').innerHTML='<div class="modal-eyebrow">NEW VOYAGE</div><h2>Leave this story behind?</h2><p class="intro">This will replace your saved voyage, gold, cargo, and discoveries on this device.</p><button id="confirm-restart" class="action-btn">Begin a new voyage</button> <button id="cancel-restart" class="action-btn">Keep my voyage</button>';$('confirm-restart').onclick=()=>{state=newGame();target=null;velocity=0;pirateHull=100;world.npc.visible=true;closeModal();updateHUD();toast('A fresh start. Fair winds, Captain.');};$('cancel-restart').onclick=settings;};}let highQuality=true;$('settings').onclick=settings;
function fire(){if(paused||modal.open)return;if(fireCooldown>0){toast('The crew is reloading the cannons.');return;}fireCooldown=4;world.burst(state.x+Math.cos(state.heading)*1.5,state.z-Math.sin(state.heading)*1.5,'#edd0a1');sound(75,.7,'sawtooth');const d=Math.hypot(state.x-world.npc.position.x,state.z-world.npc.position.z);if(d<18&&pirateHull>0){pirateHull-=34;world.burst(world.npc.position.x,world.npc.position.z,'#c48755');if(pirateHull<=0){state.gold+=250;state.log.push('Defeated a corsair and collected a 250 gold bounty.');world.npc.visible=false;toast('Corsair defeated! +250 gold bounty.');save();}else toast(`Direct hit! Corsair hull: ${Math.max(0,pirateHull)}%.`);}else toast('Broadside fired. No hostile ship within range.');}$('fire').onclick=fire;
addEventListener('keydown',e=>{if(modal.open)return;const key=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' '].includes(key))e.preventDefault();keys.add(key);if(e.repeat)return;if(key==='e')enterPort();if(key==='c')openCargo();if(key==='m')openChart();if(key==='j')openJournal();if(key==='p'||key==='escape')pause();if(key===' ')fire();});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',()=>keys.clear());addEventListener('beforeunload',save);document.addEventListener('visibilitychange',()=>{keys.clear();lastTime=performance.now();if(document.hidden)save();});
function updateHUD(){$('gold').textContent=Math.floor(state.gold).toLocaleString();$('provisions').textContent=Math.ceil(state.supplies);$('hull-label').textContent=Math.floor(state.hull)+'% hull';$('hull-bar').style.width=state.hull+'%';$('hull-bar').style.background=state.hull<35?'#d38b69':'#9bbda0';$('speed').textContent=(velocity*2.2).toFixed(1);$('sail-state').textContent=paused?'VOYAGE PAUSED':state.sail===0?'ANCHOR LOWERED':target?'COURSE PLOTTED':state.sail<1?'HALF SAIL':'FULL SAIL';document.querySelectorAll('[data-sail]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.sail)===state.sail));const day=Math.floor(state.time/1440)+1,h=Math.floor(state.time%1440/60),m=Math.floor(state.time%60);$('date').textContent=`Day ${day} · ${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`;$('needle').style.transform=`rotate(${-state.heading*180/Math.PI}deg)`;$('coordinates').textContent=`${(23-state.z*.1).toFixed(1)}° N   ${(14+state.x*.1).toFixed(1)}° E`;$('dock').disabled=!nearPort;$('dock').innerHTML=nearPort?'<span>⚓</span> Enter port <kbd>E</kbd>':'<span>⚓</span> At sea';$('destination-status').textContent=target?`Sailing to ${target.label} · ${Math.ceil(Math.hypot(target.x-state.x,target.z-state.z))} leagues`:'';$('fire').style.opacity=fireCooldown>0?'.5':'1';if(state.quest===0){$('quest-text').textContent='Buy 3 saffron in Port Aurelia and deliver it to Bellhaven.';$('quest-step').textContent='A merchant’s first voyage';$('quest-hint').textContent=`Saffron aboard: ${state.cargo.saffron} / 3`;}else if(state.quest===1){$('quest-text').textContent='Sail northeast to Bellhaven. Sell 3 crates of saffron for a 500 gold commission.';$('quest-step').textContent='Deliver the precious cargo';$('quest-hint').textContent=`Delivered: ${state.delivered||0} / 3 crates`;}else if(state.quest===2){$('quest-text').textContent='Seek the forgotten island southwest of Port Aurelia. Approach its eastern shore.';$('quest-step').textContent='The Sunken Observatory';$('quest-hint').textContent='Discovery reward: 750 gold';}else{$('quest-text').textContent='A new trade route. An ancient discovery. The isles are yours to explore.';$('quest-step').textContent='A captain in your own right';$('quest-hint').textContent='Continue trading and exploring';}$('quest-stage').textContent=state.quest<2?'01':'02';}
let lastLocation='';function simulation(dt){fireCooldown=Math.max(0,fireCooldown-dt);pirateCooldown=Math.max(0,pirateCooldown-dt);if(keys.has('w')||keys.has('arrowup')){state.sail=1;target=null;}if(keys.has('s')||keys.has('arrowdown')){state.sail=0;target=null;}if(keys.has('a')||keys.has('arrowleft')){state.heading+=dt*.85;target=null;}if(keys.has('d')||keys.has('arrowright')){state.heading-=dt*.85;target=null;}if(target){const dx=target.x-state.x,dz=target.z-state.z,d=Math.hypot(dx,dz);if(d<1.8){toast(`Arrived at ${target.label}.`);target=null;state.sail=0;}else{const desired=Math.atan2(dx,dz);let diff=Math.atan2(Math.sin(desired-state.heading),Math.cos(desired-state.heading));state.heading+=Math.max(-dt*.9,Math.min(dt*.9,diff));}}
const wanted=state.sail*3.4*(state.supplies>0?1:.4);velocity+=(wanted-velocity)*(1-Math.exp(-dt*.8));const nx=state.x+Math.sin(state.heading)*velocity*dt,nz=state.z+Math.cos(state.heading)*velocity*dt;const obstacles=[...PORTS,RUIN,{x:-62,z:-43,r:7},{x:1,z:-66,r:8},{x:65,z:-3,r:6},{x:-63,z:14,r:4}];if(obstacles.some(p=>Math.hypot(nx-p.x,nz-p.z)<p.r*1.03)||Math.abs(nx)>85||Math.abs(nz)>85){if(velocity>.5){toast('Shallow water ahead. Turn your ship toward open sea.');}state.sail=0;velocity=0;target=null;}else{state.x=nx;state.z=nz;}
state.time+=dt*2;state.supplies=Math.max(0,state.supplies-dt/720);nearPort=PORTS.find(p=>Math.hypot(state.x-p.harbor.x,state.z-p.harbor.z)<10)||null;const nearest=[...PORTS].sort((a,b)=>Math.hypot(state.x-a.x,state.z-a.z)-Math.hypot(state.x-b.x,state.z-b.z))[0];const location=Math.hypot(state.x-nearest.x,state.z-nearest.z)<30?nearest.name:'The Sapphire Reach';if(location!==lastLocation){lastLocation=location;$('location-name').textContent=location;$('location-desc').textContent=location==='The Sapphire Reach'?'Open sea · The Emerald Isles':nearest.id==='aurelia'?'The heart of the Emerald Isles':nearest.id==='bellhaven'?'Where the northern trade winds meet':'A haven at the edge of the world';}
if(state.quest===2&&Math.hypot(state.x-RUIN.x,state.z-RUIN.z)<14){state.quest=3;state.gold+=750;state.discovered.push('observatory');state.log.push('Discovered the Sunken Observatory. Earned 750 gold and a place in the history of the isles.');toast('Discovery! The Sunken Observatory · +750 gold');sound(880,.8);save();}const pd=Math.hypot(state.x-world.npc.position.x,state.z-world.npc.position.z);if(pd<15&&pirateHull>0&&pirateCooldown===0){pirateCooldown=6;state.hull=Math.max(0,state.hull-8);world.burst(state.x,state.z,'#d7d9c4');toast('Corsair attack! Press Space to return fire, or sail out of range.');if(state.hull<=0){state.hull=60;state.gold=Math.max(0,state.gold-200);state.x=0;state.z=12;state.sail=0;velocity=0;target=null;toast('Rescued by the Aurelia coastguard. Repairs cost 200 gold.');save();}}}
function frame(now){const dt=Math.min((now-lastTime)/1000,.05);lastTime=now;const running=!paused&&!modal.open&&!document.hidden;if(running){elapsed+=dt;simulation(dt);}world.update(running?dt:0,elapsed,state,velocity,target);for(const p of PORTS){const point=world.project(p.harbor.x,2,p.harbor.z);p.label.style.left=point.x+'px';p.label.style.top=point.y+'px';p.label.style.display=point.visible?'':'none';}const rp=world.project(RUIN.x,7,RUIN.z);ruinLabel.style.left=rp.x+'px';ruinLabel.style.top=rp.y+'px';ruinLabel.style.display=rp.visible?'':'none';if(state.quest===3)ruinLabel.querySelector('.name').textContent='Sunken Observatory';hudTimer+=dt;saveTimer+=dt;if(hudTimer>.12){updateHUD();drawMap($('minimap'));if(largeMap)drawMap(largeMap,true);hudTimer=0;}if(saveTimer>8){save();saveTimer=0;}requestAnimationFrame(frame);}updateHUD();requestAnimationFrame(frame);
setTimeout(()=>{if(state.quest===0)toast('Welcome aboard, Captain. Click Port Aurelia’s harbor to begin.');},1400);
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'read_voyage',title:'Read current voyage',description:'Read the ship position, cargo, gold, supplies, objective and nearby harbor without changing the game.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return{gold:state.gold,cargo:{...state.cargo},hull:state.hull,supplies:Math.ceil(state.supplies),position:{x:state.x,z:state.z},quest:state.quest,nearbyPort:nearPort?.id||null,target:target?{...target}:null};}});register({name:'plot_course_to_port',title:'Plot course to a port',description:'Start sailing toward a named harbor using the same navigation as the harbor marker. Does not enter the port or trade.',inputSchema:{type:'object',properties:{port:{type:'string',enum:PORTS.map(p=>p.id)}},required:['port'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const p=PORTS.find(p=>p.id===input?.port);if(!p)throw Error('Choose aurelia, bellhaven, or verdant.');if(paused||modal.open)throw Error('Resume the voyage and close the current panel first.');navigate(p.harbor.x,p.harbor.z,p.name);return{destination:p.name,course:{x:p.harbor.x,z:p.harbor.z}};}});addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
